<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('payments.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';require __DIR__.'/purchase_helpers.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$customerId=(int)$_POST['customer_id'];$amount=(float)$_POST['amount'];$db->beginTransaction();try{if($amount<=0)throw new RuntimeException('Enter the amount received.');$c=$db->prepare('SELECT * FROM customers WHERE id=? FOR UPDATE');$c->execute([$customerId]);$customer=$c->fetch();if(!$customer)throw new RuntimeException('Choose a customer.');$receipt=next_number($db,'customer_payments','REC');$db->prepare('INSERT INTO customer_payments(receipt_no,customer_id,payment_date,amount,method,reference_no,allocation_mode,notes,collected_by) VALUES(?,?,NOW(),?,?,?,"oldest",?,?)')->execute([$receipt,$customerId,$amount,$_POST['method'],trim($_POST['reference_no']),trim($_POST['notes']),user()['id']]);$paymentId=(int)$db->lastInsertId();$remaining=$amount;$bills=$db->prepare('SELECT * FROM sales WHERE customer_id=? AND balance>0 AND status IN("unpaid","partially_paid","overdue") ORDER BY sale_date,id FOR UPDATE');$bills->execute([$customerId]);foreach($bills as $bill){if($remaining<=0)break;$applied=min($remaining,(float)$bill['balance']);$newBalance=(float)$bill['balance']-$applied;$db->prepare('INSERT INTO customer_payment_allocations(payment_id,sale_id,amount) VALUES(?,?,?)')->execute([$paymentId,$bill['id'],$applied]);$db->prepare('UPDATE sales SET paid_amount=paid_amount+?,balance=?,status=? WHERE id=?')->execute([$applied,$newBalance,$newBalance<=0?'paid':'partially_paid',$bill['id']]);$remaining-=$applied;}$applied=$amount-$remaining;$db->prepare('UPDATE customers SET outstanding=GREATEST(0,outstanding-?),total_payments=total_payments+?,last_payment_at=NOW() WHERE id=?')->execute([$applied,$amount,$customerId]);audit($db,'create','customer_payment',$paymentId,null,['receipt_no'=>$receipt,'amount'=>$amount,'allocated'=>$applied,'advance'=>$remaining]);$db->commit();flash('success',"Payment $receipt saved. Oldest bills were paid first.".($remaining>0?' Extra advance: '.money($remaining):''));redirect('payments.php');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('payments.php');}}
$customers=$db->query('SELECT * FROM customers WHERE status="active" AND (credit_enabled=1 OR outstanding>0) ORDER BY name')->fetchAll();$rows=$db->query('SELECT p.*,c.name customer FROM customer_payments p JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC LIMIT 30')->fetchAll();page_start('Receive Customer Payment','payments.php');?>
<section class="action-banner"><div><span class="step-number">1</span><div><b>Customer gives money for an old credit bill</b><p>Choose the customer and amount. The system pays their oldest unpaid bill first.</p></div></div></section><div class="page-grid"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Recent receipts</span><h3>Payments already received</h3></div></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Date</th><th>Method</th><th class="right">Amount</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="empty-state compact"><b>No receipts yet</b></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['receipt_no'])?></b></td><td><?=e($r['customer'])?></td><td><?=date('d M Y, H:i',strtotime($r['payment_date']))?></td><td><span class="tag"><?=e(str_replace('_',' ',$r['method']))?></span></td><td class="right"><b><?=money($r['amount'])?></b></td></tr><?php endforeach;?></tbody></table></div></section><aside class="panel"><div class="panel-head"><div><span class="eyebrow">New receipt</span><h3>Record money received</h3></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf()?>"><label class="full">Customer<select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> — owes <?=money($c['outstanding'])?></option><?php endforeach;?></select></label><label class="full">Amount received<input type="number" name="amount" min=".01" step=".01" required></label><label>Received using<select name="method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option></select></label><label>Reference<input name="reference_no"></label><label class="full">Notes<textarea name="notes" rows="2"></textarea></label><div class="plain-help full">We automatically apply this money to the oldest unpaid invoice. Every payment keeps its own receipt.</div><button class="btn primary full">Save Payment & Receipt</button></form></aside></div><?php page_end();

